  "Acertar o número com a fórmula errada é o que mais acontece no trabalho, e é o que quebra quando a base cresce. Aqui os dois são conferidos, e o atalho perigoso vira alerta.": {
    "en": "Getting the number right with the wrong formula is the most common mistake at work, and it breaks when the data grows. Here both are checked, and the risky shortcut becomes an alert.",
    "es": "Acertar el número con la fórmula equivocada es lo que más ocurre en el trabajo, y es lo que falla cuando la base crece. Aquí ambos se verifican, y el atajo peligroso se vuelve alerta."
  },
