  "CSV até 1 MB · 5.000 linhas · 40 colunas. Processado neste navegador.": {
    "en": "CSV up to 1 MB · 5,000 rows · 40 columns. Processed in this browser.",
    "es": "CSV hasta 1 MB · 5.000 filas · 40 columnas. Procesado en este navegador."
  },
  "CSV da etapa": {
    "en": "Step CSV",
    "es": "CSV de la etapa"
  },
  "CT2 tem lançamento de partida dobrada: somar a coluna de valor sem separar débito e crédito dá o dobro do movimento.": {
    "en": "CT2 has double‑entry posting: summing the value column without separating debit and credit doubles the movement.",
    "es": "CT2 tiene lanzamiento de partida doble: sumar la columna de valor sin separar débito y crédito da el doble del movimiento."
  },
  "CTT é o cadastro de centro de custo, CT1 o plano de contas e CT2 os lançamentos contábeis.": {
    "en": "CTT is the cost‑center register, CT1 the chart of accounts and CT2 the accounting entries.",
    "es": "CTT es el registro de centro de costo, CT1 el plan de cuentas y CT2 los asientos contables."
  },
  "Cada aba é um bloco pronto, com comentário explicando a decisão. Embaixo está a ordem em que colar no Power BI, incluindo marcar a tabela como tabela de datas.": {
    "en": "Each tab is a ready block, with a comment explaining the decision. Below is the order to paste into Power BI, including marking the table as a date table.",
    "es": "Cada pestaña es un bloque listo, con comentario explicando la decisión. Debajo está el orden en que pegar en Power BI, incluyendo marcar la tabla como tabla de fechas."
  },
  "Cada ciclo começa com um acontecimento do mercado. Ele muda a procura, então vale ler antes de mexer em preço e estoque.": {
    "en": "Each cycle starts with a market event. It changes demand, so read before adjusting price and inventory.",
    "es": "Cada ciclo comienza con un acontecimiento del mercado. Cambia la demanda, así que vale leer antes de cambiar precio y stock."
  },
  "Cada competência vai de 0 a 100 e soma cinco tipos de evidência:": {
    "en": "Each skill ranges 0‑100 and adds five evidence types:",
    "es": "Cada competencia va de 0 a 100 y suma cinco tipos de evidencia:"
  },
  "Cada estação é uma etapa real do seu fluxo. Gire com o mouse, aproxime com a roda e clique em uma estação para inspecionar. Se preferir, troque para 2D no canto.": {
    "en": "Each station is a real step of your flow. Rotate with the mouse, zoom with the wheel and click a station to inspect. If you prefer, switch to 2D in the corner.",
    "es": "Cada estación es una etapa real de tu flujo. Gira con el ratón, acerca con la rueda y haz clic en una estación para inspeccionar. Si prefieres, cambia a 2D en la esquina."
  },
  "Cada estação é uma transformação real dos seus dados. A linha do tempo reproduz uma execução já concluída para você investigar etapa por etapa; ela não mede o tempo de processamento.": {
    "en": "Each station is a real transformation of your data. The timeline plays a completed run for you to investigate step by step; it does not measure processing time.",
    "es": "Cada estación es una transformación real de tus datos. La línea de tiempo reproduce una ejecución ya concluida para que investigues paso a paso; no mide el tiempo de procesamiento."
  },
  "Cada estrela com nome representa uma competência. Explore seu domínio registrado e use a linha do tempo para acompanhar sua evolução — essa é a quarta dimensão.": {
    "en": "Each named star represents a skill. Explore your recorded mastery and use the timeline to track your progress — this is the fourth dimension.",
    "es": "Cada estrella con nombre representa una competencia. Explora tu dominio registrado y usa la línea de tiempo para seguir tu evolución — esa es la cuarta dimensión."
  },
  "Cada estrela é uma competência sua. Quanto mais evidência você acumula, mais forte ela brilha. Gire e aproxime para explorar.": {
    "en": "Each star is your skill. The more evidence you gather, the brighter it shines. Spin and zoom to explore.",
    "es": "Cada estrella es una competencia tuya. Cuanta más evidencia acumules, más fuerte brillará. Gira y acerca para explorar."
  },
  "Cada execução guarda a anterior. É assim que você prova que a limpeza corrigiu o faturamento inflado, com número na tela.": {
    "en": "Each run stores the previous one. That’s how you prove the cleanup fixed inflated billing, with the number on screen.",
    "es": "Cada ejecución guarda la anterior. Así demuestras que la limpieza corrigió el facturación inflada, con número en pantalla."
  },
  "Cada faixa preenche até o valor indicado (verde/amarelo/vermelho).": {
    "en": "Each band fills up to the indicated value (green/yellow/red).",
    "es": "Cada banda llena hasta el valor indicado (verde/amarillo/rojo)."
  },
  "Cada fusão junta o par de pedaços mais comum. Menos fusões, tokens menores.": {
    "en": "Each merge joins the most common piece pair. Fewer merges, smaller tokens.",
    "es": "Cada fusión une el par de fragmentos más común. Menos fusiones, tokens menores."
  },
  "Cada laudo fica no seu histórico. Corrija o que apareceu, suba o mesmo arquivo de novo e veja a nota subir. É assim que isso vira aprendizado, e não só diagnóstico.": {
    "en": "Each report stays in your history. Fix what appeared, upload the same file again and see the score rise. That’s how it becomes learning, not just diagnosis.",
    "es": "Cada informe queda en tu historial. Corrige lo que apareció, sube el mismo archivo de nuevo y ve la nota subir. Así se convierte en aprendizaje, no solo diagnóstico."
  },
  "Cada linha traz o título e o quando usar. Muitas vezes isso basta para você saber se é o verbete certo. As setas do teclado andam na lista.": {
    "en": "Each line gives the title and when to use it. Often that’s enough for you to know if it’s the right entry. The keyboard arrows move through the list.",
    "es": "Cada línea trae el título y cuándo usar. A menudo basta para saber si es el término correcto. Las flechas del teclado se mueven en la lista."
  },
  "Cada pedaço vira bytes. Acento e emoji ocupam mais de um, e é aí que o português começa a ficar caro.": {
    "en": "Each piece becomes bytes. Accents and emojis take more than one, and that’s where Portuguese gets costly.",
    "es": "Cada fragmento se vuelve bytes. Acentos y emojis ocupan más de uno, y ahí el portugués se vuelve caro."
  },
