  "Com ALL na tabela inteira, o total ignora até o filtro de ano, e a soma das participações deixa de dar 100%.": {
    "en": "With ALL on the whole table, the total ignores even the year filter, and the sum of shares no longer equals 100%.",
    "es": "Con ALL en la tabla completa, el total ignora incluso el filtro de año, y la suma de participaciones deja de dar 100%."
  },
  "Com ALL, o ranking considera produtos que o usuário filtrou fora, e ele vê a posição 7 sem ver as seis primeiras.": {
    "en": "With ALL, the ranking includes products the user filtered out, so they see rank 7 without the first six.",
    "es": "Con ALL, el ranking considera productos que el usuario filtró fuera, y ve la posición 7 sin ver las seis primeras."
  },
  "Com a fórmula certa, o número da sua base é": {
    "en": "With the right formula, your base number is",
    "es": "Con la fórmula correcta, el número de tu base es"
  },
  "Com junção comum essas linhas simplesmente somem, e o relatório fecha menor sem nenhum aviso.": {
    "en": "With a regular join those rows just disappear, and the report comes out lower with no warning.",
    "es": "Con unión común esas filas simplemente desaparecen, y el informe queda menor sin aviso."
  },
  "Com o tempo, a atualidade pode diminuir. Isso é um convite à revisão: a passagem do tempo, por si só, não retira seu score, seus certificados ou suas conquistas.": {
    "en": "Over time, relevance may fade. This invites review: time alone doesn't erase your score, certificates, or achievements.",
    "es": "Con el tiempo, la actualidad puede disminuir. Esto es una invitación a la revisión: el paso del tiempo, por sí solo, no quita tu puntuación, tus certificados o tus logros."
  },
  "Com uma tabela de calendário ligada, a lista de meses vem dela. Sem calendário, dá para usar VALUES na coluna de data do próprio fato.": {
    "en": "With a linked calendar table, the month list comes from it. Without a calendar, you can use VALUES on the fact’s date column.",
    "es": "Con una tabla de calendario vinculada, la lista de meses proviene de ella. Sin calendario, se puede usar VALUES en la columna de fecha del propio hecho."
  },
