  "DA ANÁLISE À AÇÃO": {
    "en": "FROM ANALYSIS TO ACTION",
    "es": "DEL ANÁLISIS A LA ACCIÓN"
  },
  "DATE no Oracle sempre carrega hora. TRUNC zera a hora e deixa o dia limpo.": {
    "en": "Oracle DATE always includes time. TRUNC clears the time, leaving a clean day.",
    "es": "DATE en Oracle siempre lleva hora. TRUNC elimina la hora y deja el día limpio."
  },
  "DATEADD anda no calendário, e não na tabela de fatos, então funciona mesmo em mês sem venda.": {
    "en": "DATEADD moves on the calendar, not the fact table, so it works even in a month with no sales.",
    "es": "DATEADD avanza en el calendario, no en la tabla de hechos, así funciona aunque el mes no tenga ventas."
  },
  "DATEADD e DATEDIFF não existem no Oracle. MONTHS_BETWEEN devolve número quebrado, então arredonde quando for contar mês cheio.": {
    "en": "DATEADD and DATEDIFF don’t exist in Oracle. MONTHS_BETWEEN returns a fractional number, so round when counting full months.",
    "es": "DATEADD y DATEDIFF no existen en Oracle. MONTHS_BETWEEN devuelve número decimal, redondea al contar mes completo."
  },
  "DATESINPERIOD monta a janela de três meses terminando na data em contexto.": {
    "en": "DATESINPERIOD builds a three‑month window ending on the current date.",
    "es": "DATESINPERIOD crea la ventana de tres meses terminando en la fecha del contexto."
  },
  "DAX e Excel ficam aqui, com a mesma base nas duas trilhas: é a melhor forma de ver como cada ferramenta resolve a mesma pergunta. O treino de SQL fica na Arena, com banco de verdade.": {
    "en": "DAX and Excel stay here, with the same base in both tracks: it’s the best way to see how each tool answers the same question. SQL training is in the Arena, with a real database.",
    "es": "DAX y Excel están aquí, con la misma base en ambas rutas: es la mejor forma de ver cómo cada herramienta resuelve la misma pregunta. El entrenamiento de SQL está en la Arena, con base real."
  },
