  "Monte e opere um modelo de linguagem dentro do seu navegador. Veja o texto virar token, o corpus virar tabela de probabilidade e a frase ser escrita um token por vez, com os candidatos à vista. Sem API, sem chave e sem custo.": {
    "en": "Build and run a language model in your browser. Watch text become tokens, the corpus become a probability table and the sentence be written one token at a time, with candidates visible. No API, no key, no cost.",
    "es": "Construye y opera un modelo de lenguaje dentro de tu navegador. Ve el texto convertirse en token, el corpus en tabla de probabilidad y la frase escribirse un token a la vez, con los candidatos a la vista. Sin API, sin clave y sin costo."
  },
