  "Mudou de ideia? Vote de novo com o mesmo e-mail que a resposta é substituída.": {
    "en": "Changed your mind? Vote again with the same email and the answer is replaced.",
    "es": "¿Cambiaste de idea? Vota de nuevo con el mismo e‑mail y la respuesta se sustituye."
  },
  "Muita gente tenta resolver ano fiscal com filtro no visual. Não resolve: o acumulado continua reiniciando em janeiro.": {
    "en": "Many people try to fix fiscal year with a visual filter. It doesn't work: the cumulative keeps restarting in January.",
    "es": "Mucha gente intenta resolver el año fiscal con filtro en la visualización. No funciona: el acumulado sigue reiniciando en enero."
  },
  "MÁXIMO ou MÁXIMOSES": {
    "en": "MAX or MAXX",
    "es": "MÁXIMO o MÁXIMOSES"
  },
  "MÁXIMOSES não aceita expressão calculada, só coluna. Por isso entra o MÁXIMO com SE em matriz, ou uma coluna auxiliar com o líquido.": {
    "en": "MAXX does not accept a calculated expression, only a column. That's why you use MAX with IF in a matrix, or an auxiliary column with the net.",
    "es": "MÁXIMOSES no acepta expresión calculada, solo columna. Por eso se usa MÁXIMO con SI en matriz, o una columna auxiliar con el líquido."
  },
  "MÉDIASES": {
    "en": "AVERAGEX",
    "es": "MÉDIASES"
  },
  "MÉDIASES ignora as linhas que não atendem ao critério. Somar e dividir na mão pelo total de linhas dá um número menor e errado.": {
    "en": "AVERAGEX ignores rows that don't meet the criteria. Summing and dividing manually by total rows gives a smaller, wrong number.",
    "es": "MÉDIASES ignora las filas que no cumplen el criterio. Sumar y dividir manualmente por el total de filas da un número menor y erróneo."
  },
