  "NOT EXISTS para na primeira linha que encontra, então costuma ser mais rápido que NOT IN.": {
    "en": "NOT EXISTS stops at the first matching row, so it's usually faster than NOT IN.",
    "es": "NOT EXISTS para la primera fila que encuentra, por lo que suele ser más rápido que NOT IN."
  },
  "NOT IN com uma subconsulta que devolve nulo retorna vazio, sempre, sem erro nenhum. É o bug mais silencioso do SQL.": {
    "en": "NOT IN with a subquery that returns null returns empty, always, no error. It's the quietest SQL bug.",
    "es": "NOT IN con una subconsulta que devuelve nulo retorna vacío, siempre, sin error alguno. Es el bug más silencioso del SQL."
  },
  "NULL quem? Exatamente.": {
    "en": "NULL who? Exactly.",
    "es": "NULL ¿quién? Exactamente."
  },
  "NVL troca o nulo, NVL2 escolhe entre dois caminhos e COALESCE pega o primeiro que não for nulo.": {
    "en": "NVL replaces null, NVL2 chooses between two paths and COALESCE takes the first non‑null.",
    "es": "NVL cambia el nulo, NVL2 elige entre dos caminos y COALESCE toma el primero que no sea nulo."
  },
  "Na Academy você aprende construindo, com as ferramentas, os desafios e a comunidade do lado. O que sai daqui vira portfólio, e portfólio é o que abre porta.": {
    "en": "In the Academy you learn by building, with the tools, the challenges and the community by your side. What you get out of here becomes a portfolio, and a portfolio opens doors.",
    "es": "En la Academy aprendes construyendo, con las herramientas, los desafíos y la comunidad al lado. Lo que sale aquí se vuelve portafolio, y el portafolio es lo que abre puertas."
  },
  "Na Arena SQL a base é gerada só para você, e quando você erra eu digo exatamente onde.": {
    "en": "In Arena SQL the base is generated just for you, and when you mess up I tell you exactly where.",
    "es": "En Arena SQL la base se genera solo para ti, y cuando fallas te digo exactamente dónde."
  },
  "Na Caixa-Preta você monta um modelo de linguagem no navegador e vê a probabilidade de cada token.": {
    "en": "In Caixa-Preta you build a language model in the browser and see each token’s probability.",
    "es": "En Caja-Preta montas un modelo de lenguaje en el navegador y ves la probabilidad de cada token."
  },
  "Na Vitrine, empresas e colegas veem seu perfil. Foto e LinkedIn preenchidos fazem diferença.": {
    "en": "In the Vitrine, companies and peers see your profile. Photo and LinkedIn filled make a difference.",
    "es": "En la Vitrina, empresas y colegas ven tu perfil. Foto y LinkedIn completos hacen diferencia."
  },
