  "Os modos do universo": {
    "en": "The modes of the universe",
    "es": "Los modos del universo"
  },
  "Os números foram sorteados a partir do seu cadastro, então a resposta do colega não fecha aqui. Quer treinar de novo com outros números? Nova base.": {
    "en": "Numbers were drawn from your registration, so the colleague’s answer doesn’t fit here. Want to train again with new numbers? New set.",
    "es": "Los números fueron sorteados a partir de tu registro, entonces la respuesta del colega no cierra aquí. ¿Quieres entrenar de nuevo con otros números? Nueva base."
  },
  "Os primeiros artigos estão a caminho.": {
    "en": "The first articles are on the way.",
    "es": "Los primeros artículos están en camino."
  },
  "Os primeiros marcos aparecem quando uma competência alcança 50/100. Avance a timeline para acompanhar.": {
    "en": "The first milestones appear when a skill reaches 50/100. Advance the timeline to follow.",
    "es": "Los primeros hitos aparecen cuando una competencia alcanza 50/100. Avanza la línea de tiempo para seguir."
  },
  "Os primeiros projetos estão sendo preparados": {
    "en": "The first projects are being prepared.",
    "es": "Los primeros proyectos están siendo preparados."
  },
  "Os resultados seguem regras da plataforma, sem avaliação por inteligência artificial.": {
    "en": "Results follow platform rules, no AI evaluation.",
    "es": "Los resultados siguen reglas de la plataforma, sin evaluación por inteligencia artificial."
  },
  "Os treinamentos completos saem por um valor especial, pago uma vez só. O curso fica com você, com aulas, materiais e avaliação.": {
    "en": "Complete trainings are available for a special one‑time price. The course stays with you, with lessons, materials and assessment.",
    "es": "Los entrenamientos completos salen por un valor especial, pagado una sola vez. El curso te queda, con clases, materiales y evaluación."
  },
  "Os treinamentos estão inclusos?": {
    "en": "Are trainings included?",
    "es": "¿Están incluidos los entrenamientos?"
  },
  "Os três maiores de cada categoria": {
    "en": "The three largest in each category",
    "es": "Los tres mayores de cada categoría"
  },
  "Os índices do Protheus quase sempre começam pela filial. Respeitar essa ordem é o que separa três segundos de três minutos.": {
    "en": "Protheus indexes almost always start with the branch. Respecting this order separates three seconds from three minutes.",
    "es": "Los índices de Protheus casi siempre empiezan por la sucursal. Respetar ese orden es lo que separa tres segundos de tres minutos."
  },
  "Outro chamado": {
    "en": "Another call",
    "es": "Otro llamado"
  },
  "Outros membros já podem ver, votar e usar o seu visual como ponto de partida.": {
    "en": "Other members can already see, vote and use your visual as a starting point.",
    "es": "Otros miembros ya pueden ver, votar y usar tu visual como punto de partida."
  },
  "PARTITION BY reinicia a numeração a cada categoria.": {
    "en": "PARTITION BY restarts numbering for each category.",
    "es": "PARTITION BY reinicia la numeración en cada categoría."
  },
  "PBIX permite revisar a estrutura do relatório. PBIT pode disponibilizar também o modelo. Dimensões sem evidência ficam sem nota. Para exportar um PBIT, abra Arquivo → Exportar → Modelo do Power BI.": {
    "en": "PBIX lets you review the report structure. PBIT can also provide the model. Dimensions without evidence get no score. To export a PBIT, open File → Export → Power BI Model.",
    "es": "PBIX permite revisar la estructura del informe. PBIT también puede disponibilizar el modelo. Dimensiones sin evidencia quedan sin nota. Para exportar un PBIT, abre Archivo → Exportar → Modelo de Power BI."
  },
