  "Para comparar versões, informe o mesmo nome de projeto. A comparação exige as mesmas dimensões avaliadas e a mesma versão das regras. Uma análise local registra participação autodeclarada, não proficiência comprovada.": {
    "en": "To compare versions, enter the same project name. Comparison requires the same evaluated dimensions and the same rule version. A local analysis records self‑declared participation, not proven proficiency.",
    "es": "Para comparar versiones, indica el mismo nombre de proyecto. La comparación exige las mismas dimensiones evaluadas y la misma versión de las reglas. Un análisis local registra participación autodeclarada, no competencia comprobada."
  },
