  "São 25 perguntas rápidas e você responde uma vez só.": {
    "en": "There are 25 quick questions and you answer only once.",
    "es": "Son 25 preguntas rápidas y respondes solo una vez."
  },
  "São competências. Quanto maior a estrela, maior o domínio evidenciado.": {
    "en": "These are skills. The higher the star, the greater the demonstrated mastery.",
    "es": "Son competencias. Cuanto mayor la estrella, mayor el dominio evidenciado."
  },
  "São oportunidades: ainda não há pontuação registrada para aquela competência.": {
    "en": "These are opportunities: no score has been recorded for that skill yet.",
    "es": "Son oportunidades: aún no hay puntuación registrada para esa competencia."
  },
  "São três colunas na mesma conta, linha a linha.": {
    "en": "There are three columns in the same account, row by row.",
    "es": "Son tres columnas en la misma cuenta, fila a fila."
  },
  "Série mês a mês que ordena sozinha": {
    "en": "Month‑by‑month series that orders itself.",
    "es": "Serie mes a mes que ordena sola"
  },
  "Só agora vale a pena olhar lançamento a lançamento. A coluna de situação marca o que está só de um lado, com valor diferente ou com id repetido.": {
    "en": "Now it’s worth looking at each release. The status column marks what is only on one side, with a different value or repeated ID.",
    "es": "Solo ahora vale la pena mirar lanzamiento a lanzamiento. La columna de situación marca lo que está solo de un lado, con valor diferente o con id repetido."
  },
  "Só de CALCULATE sem REMOVEFILTERS.": {
    "en": "Only CALCULATE without REMOVEFILTERS.",
    "es": "Solo CALCULATE sin REMOVEFILTERS."
  },
  "Só funciona com uma tabela de calendário marcada como tabela de datas. Sem isso o número parece certo e erra nas bordas do ano.": {
    "en": "Works only with a calendar table marked as a date table. Without it the number looks right but misses at year edges.",
    "es": "Solo funciona con una tabla de calendario marcada como tabla de fechas. Sin eso el número parece correcto y falla en los bordes del año."
  },
  "TEMPO SIMULADO": {
    "en": "SIMULATED TIME",
    "es": "TIEMPO SIMULADO"
  },
  "TOPN devolve uma tabela com os dez primeiros, e KEEPFILTERS soma dentro do que já estava filtrado.": {
    "en": "TOPN returns a table with the first ten, and KEEPFILTERS sums within what was already filtered.",
    "es": "TOPN devuelve una tabla con los diez primeros, y KEEPFILTERS suma dentro de lo que ya estaba filtrado."
  },
  "TOTALYTD respeita o filtro do visual e reinicia a contagem a cada ano.": {
    "en": "TOTALYTD respects the visual filter and resets the count each year.",
    "es": "TOTALYTD respeta el filtro visual y reinicia el conteo cada año."
  },
  "TRAJETÓRIA DO PEDIDO": {
    "en": "ORDER TRAJECTORY",
    "es": "TRAYECTORIA DEL PEDIDO"
  },
  "Tabela compartilhada tem filial em branco, e tabela exclusiva tem o código. Filtrar errado zera o resultado ou soma empresas diferentes. O modo de compartilhamento está no SX2, campo X2_MODO.": {
    "en": "Shared table has blank branch, exclusive table has the code. Wrong filter zeros the result or sums different companies. Sharing mode is in SX2, field X2_MODE.",
    "es": "La tabla compartida tiene sucursal en blanco, y la tabla exclusiva tiene el código. Filtrar mal anula el resultado o suma empresas distintas. El modo de compartición está en SX2, campo X2_MODO."
  },
